+import 'dart:io';
+import 'package:flutter/foundation.dart';
+import 'package:flutter_local_notifications/flutter_local_notifications.dart';
+
+class PermissionService {
+  static final PermissionService _instance = PermissionService._internal();
+
+  factory PermissionService() {
+    return _instance;
+  }
+
+  PermissionService._internal();
+
+  /// Fordert alle benötigten Berechtigungen beim App-Start an
+  Future<void> requestInitialPermissions() async {
+    try {
+      final flutterLocalNotificationsPlugin = FlutterLocalNotificationsPlugin();
+      
+      // Android 13+ benötigt explizite POST_NOTIFICATIONS Permission
+      if (Platform.isAndroid) {
+        // Auf Android werden Berechtigungen über flutter_local_notifications gehandhabt
+        // Versuche die Berechtigung zu fordern
+        final androidPlugin = flutterLocalNotificationsPlugin
+            .resolvePlatformSpecificImplementation<
+                AndroidFlutterLocalNotificationsPlugin>();
+        
+        if (androidPlugin != null) {
+          // Fordere POST_NOTIFICATIONS Permission an
+          final granted = await androidPlugin.requestNotificationPermission();
+          if (kDebugMode) {
+            print('✓ Android notification permission requested: $granted');
+          }
+        }
+      } else if (Platform.isIOS) {
+        // iOS Notifications Permission
+        final iosPlugin = flutterLocalNotificationsPlugin
+            .resolvePlatformSpecificImplementation<
+                IOSFlutterLocalNotificationsPlugin>();
+        
+        if (iosPlugin != null) {
+          await iosPlugin.requestPermissions(
+            alert: true,
+            badge: true,
+            sound: true,
+          );
+          
+          if (kDebugMode) {
+            print('✓ iOS notification permissions requested');
+          }
+        }
+      }
+    } catch (e) {
+      if (kDebugMode) {
+        print('❌ Error requesting permissions: $e');
+      }
+    }
+  }
+}

