+  granted('Aktiviert', Color(0xFF4CAF50)),
+  denied('Deaktiviert', Color(0xFFf44336)),
+  restricted('Eingeschränkt', Color(0xFFFFC107)),
+  unknown('Unbekannt', Color(0xFF9E9E9E));
+
+  final String label;
+  final Color color;
+
+  const PermissionStatus(this.label, this.color);
+}
