+          if (bgRestricted == true) {
+            permissions['Hintergrund-Ausführung'] = PermissionStatus.restricted;
+          } else if (bgRestricted == false) {
+            permissions['Hintergrund-Ausführung'] = PermissionStatus.granted;
+          } else {
